const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const n = data[0];
const L = data.slice(1, 1 + n);

let S = 0;
const positions = [0];
for (let i = 0; i < n; i++) {
  S += L[i];
  if (i < n - 1) positions.push(S);
}

if (S % 2 !== 0) {
  console.log('N');
} else {
  const half = S / 2;
  const set = new Set(positions);
  let count = 0;
  for (let i = 0; i < n; i++) {
    const q = positions[i] + half;
    if (set.has(q >= S ? q - S : q)) count++;
  }
  console.log(count >= 4 ? 'S' : 'N');
}
